    [Fact]
    public void Flex_direction_alternating_with_percent() {
        using var tree = new LayoutTree();

        var root = tree.CreateNode();
        tree.SetPositionType(root, PositionType.Absolute);
        tree.SetDimension(root, Dimension.Height, StyleLength.Points(300.0f));
        tree.SetDimension(root, Dimension.Width, StyleLength.Points(200.0f));

        var rootChild0 = tree.CreateNode();
        tree.SetDimension(rootChild0, Dimension.Height, StyleLength.Percent(50.0f));
        tree.SetDimension(rootChild0, Dimension.Width, StyleLength.Percent(50.0f));
        tree.SetPosition(rootChild0, Edge.Left, StyleLength.Percent(10.0f));
        tree.SetPosition(rootChild0, Edge.Top, StyleLength.Percent(10.0f));
        tree.SetFlexDirection(rootChild0, FlexDirection.Row);
        tree.InsertChild(root, rootChild0, 0);
        tree.CalculateLayout(root, float.NaN, float.NaN, Direction.Ltr);

        Assert.Equal(0.0f, tree.GetLeft(root), Tolerance);
        Assert.Equal(0.0f, tree.GetTop(root), Tolerance);
        Assert.Equal(200.0f, tree.GetWidth(root), Tolerance);
        Assert.Equal(300.0f, tree.GetHeight(root), Tolerance);

        Assert.Equal(20.0f, tree.GetLeft(rootChild0), Tolerance);
        Assert.Equal(30.0f, tree.GetTop(rootChild0), Tolerance);
        Assert.Equal(100.0f, tree.GetWidth(rootChild0), Tolerance);
        Assert.Equal(150.0f, tree.GetHeight(rootChild0), Tolerance);

        tree.CalculateLayout(root, float.NaN, float.NaN, Direction.Rtl);

        Assert.Equal(0.0f, tree.GetLeft(root), Tolerance);
        Assert.Equal(0.0f, tree.GetTop(root), Tolerance);
        Assert.Equal(200.0f, tree.GetWidth(root), Tolerance);
        Assert.Equal(300.0f, tree.GetHeight(root), Tolerance);

        Assert.Equal(120.0f, tree.GetLeft(rootChild0), Tolerance);
        Assert.Equal(30.0f, tree.GetTop(rootChild0), Tolerance);
        Assert.Equal(100.0f, tree.GetWidth(rootChild0), Tolerance);
        Assert.Equal(150.0f, tree.GetHeight(rootChild0), Tolerance);
    }
